function icon(string $name, string $class = ''): string {
    $paths = $GLOBALS['__icons'][$name] ?? '';
    $cls = trim('icon ' . $class);
    return '<svg class="' . $cls . '" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $paths . '</svg>';
}
